const fs=require('fs'),path=require('path'),http=require('http');
const root=__dirname,assets=path.join(root,'resources-1.3.3/assets/loli_labs/textures/gui/legacy');
const sprites=Object.fromEntries(fs.readdirSync(assets).map(n=>[n.slice(0,-4),'data:image/png;base64,'+fs.readFileSync(path.join(assets,n)).toString('base64')]));
Object.assign(sprites,Object.fromEntries(["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"].map((v,i)=>["reference"+i,v])));
const html=`<!doctype html><meta charset="utf-8"><title>Loli Labs — GUI preview</title><style>body{background:#14171f;color:#daf4f6;font:14px system-ui;margin:20px}main{display:flex;gap:24px;flex-wrap:wrap}canvas{width:318px;height:384px;image-rendering:pixelated}select{background:#263d49;color:white;margin:0 12px 15px 0;padding:6px}small{color:#9ab0c0}</style><h2>GUI на оригинальных ассетах LoliEnergistics</h2><p><small>Предпросмотр раскладки. Шрифт браузера отличается от игрового.</small></p><main><section><h3>Панели</h3><canvas id="solar" width="212" height="256"></canvas></section><section><h3>Объединитель</h3><canvas id="unifier" width="212" height="256"></canvas></section><section><h3>Генераторы</h3><select id="tier">${Array.from({length:10},(_,i)=>'<option value="'+i+'">T'+i+'</option>').join('')}</select><select id="batch"><option>1</option><option>6</option><option selected>12</option></select><br><canvas id="matter" width="212" height="256"></canvas></section></main><script>
const sources=${JSON.stringify(sprites)},images={};
Promise.all(Object.entries(sources).map(([k,v])=>new Promise(resolve=>{let i=new Image;i.onload=()=>{images[k]=i;resolve()};i.src=v}))).then(render);
function render(){draw('solar',0,0,1);draw('unifier',1,0,1);draw('matter',2,+tier.value,+batch.value)}
tier.onchange=batch.onchange=render;
function draw(id,kind,t,b){const g=document.getElementById(id).getContext('2d');g.imageSmoothingEnabled=false;g.clearRect(0,0,212,256);const bg=images[kind===1?'unifier':kind===2?'matter_solid_t'+t+'_x'+b:'solar'];const r=(i,x,y,w,h,u,v,sw,sh)=>g.drawImage(i,u,v,sw,sh,x,y,w,h);
if(kind===2){r(bg,0,0,212,24,0,0,212,24);r(bg,0,24,212,134,0,24,212,94);r(images.solar,0,158,212,8,0,114,212,8);g.fillStyle='#414e62';g.fillRect(12,24,188,132);for(let i=0;i<b*2+5;i++){let x,y;if(i<b*2){let lane=i%b,out=i>=b;x=b===1?(out?116:68):(out?126:34)+lane%3*18;y=(b===1?54:b===6?46:28)+Math.floor(lane/(b===1?1:3))*18;}else{x=70+(i-b*2)*18;y=120;}r(images.unifier,x-1,y-1,18,18,25,27,18,18);}r(images.unifier,43,119,18,18,25,27,18,18);r(images['reference'+t],44,120,16,16,0,0,images['reference'+t].width,images['reference'+t].width);g.fillStyle='#afb9c6';g.fillRect(102,61,10,3);g.fillRect(109,59,3,7);r(images.unifier,26,104,160,7,45,145,131,7);g.fillStyle='#35bbb9';g.fillRect(28,106,112,3);g.fillStyle='#a4fff0';g.fillRect(28,106,112,1);g.fillStyle='#657282';g.fillRect(43,143,138,12);g.fillStyle='#354152';g.fillRect(44,144,136,10);for(let i=0;i<10;i++){g.fillStyle=i<=t?'#35bbb9':'#202833';g.fillRect(110+i*6,147,4,3);}g.font='8px monospace';g.textBaseline='top';g.fillStyle='#e5fcff';g.fillText('Уровень '+(t+1),49,146);r(images.unifier,0,166,212,90,0,166,212,90);return;}if(kind===0){r(bg,0,0,212,112,0,12,212,110);g.fillStyle='#414e62';g.fillRect(12,9,188,94);g.fillStyle='#657282';g.fillRect(17,17,178,46);g.fillStyle='#354152';g.fillRect(18,18,176,44);r(images.unifier,34,65,156,7,45,145,131,7);g.fillStyle='#35bbb9';g.fillRect(36,67,110,3);g.fillStyle='#a4fff0';g.fillRect(36,67,110,1);for(let i=0;i<6;i++)r(images.unifier,52+i*18,82,18,18,25,27,18,18);r(images.unifier,0,122,212,90,0,166,212,90);g.font='8px monospace';g.textBaseline='top';g.fillStyle='#ffd34d';g.fillText('Заряд: 1.23M / 524.29G FE',23,25);g.fillText('Макс. выход: 2.15G FE/тик',23,39);g.fillText('Генерация: 33.55M FE/тик',23,53);return;}if(kind===1)r(bg,0,0,212,166,0,0,212,166);else{let bottom=kind===2?126:122;r(bg,0,0,212,24,0,0,212,24);r(bg,0,24,212,134,0,24,212,bottom-32);r(bg,0,158,212,8,0,bottom-8,212,8)}
r(images.unifier,0,166,212,90,0,166,212,90);g.fillStyle='#5cadbd';g.fillRect(25,27,162,110);r(images.unifier,26,28,160,108,26,108,160,28);r(images.unifier,26,137,160,7,26,108,160,28);let slots=images[kind===2?'matter_solid_t'+t+'_x12':'unifier'];for(let i=0;i<27;i++)r(slots,25+i%9*18,29+Math.floor(i/9)*18,18,18,25,27,18,18);r(images.unifier,26,145,160,7,45,145,131,7);g.fillStyle='#35bbb9';g.fillRect(28,147,112,3);g.fillStyle='#a4fff0';g.fillRect(28,147,112,1);g.font='8px monospace';g.textBaseline='top';g.fillStyle='#e5fcff';g.fillText('Энергия: 1.23M / 524.29G FE',29,92);g.fillStyle='#bbefee';g.fillText(kind===2?'Цикл: 12.00M FE → '+b+' шт.':'Генерация: 33.55M FE/тик',29,105);g.fillStyle='#a2c4cf';g.fillText(kind===2?'Выход материи T'+t+' x'+b:kind===1?'Панели в объединителе':'Зарядка FE-предметов',29,118);
}
</script>`;
fs.writeFileSync(path.join(root,'build/gui-preview.html'),html);
if(!process.argv.includes('--write-only'))http.createServer((req,res)=>{res.setHeader('Content-Type','text/html; charset=utf-8');res.end(fs.readFileSync(path.join(root,'build/gui-preview.html')));}).listen(8765,'127.0.0.1',()=>process.stdout.write('GUI preview: http://127.0.0.1:8765\n'));
